export function projectPage(project, tasks = [], filter = 'All', error = '', title = '') {
  const visibleTasks = tasks.filter((task) => filter === 'All' || Boolean(task.completed) === (filter === 'Completed'));
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <p id="completion-error" role="alert" hidden></p>
    <script type="module" src="/project.js"></script>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" method="post" action="/projects/${project.id}/tasks">
      <input type="hidden" name="filter" value="${escapeHtml(filter)}">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text" value="${escapeHtml(title)}">
      <button type="submit">Create task</button>
    </form>
    <form class="filter" method="get" action="/projects/${project.id}">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${['All', 'Open', 'Completed'].map((value) => `<option${value === filter ? ' selected' : ''}>${value}</option>`).join('')}
      </select>
    </form>
    <ul class="projects" aria-label="Tasks">
      ${visibleTasks.map((task) => `<li class="task" data-testid="task-row">
        <form data-task-completion method="post" action="/projects/${project.id}/tasks/${task.id}/completion">
          <input type="hidden" name="filter" value="${escapeHtml(filter)}">
          <label><input type="checkbox" name="completed" value="1" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''}><span>${escapeHtml(task.title)}</span></label>
        </form>
      </li>`).join('')}
    </ul>`);
}

export function notFoundPage() {
  return page('Page not found', '<h1>Page not found</h1><a href="/">Projects</a>');
}
export async function saveCompletion(action, completed, filter, fetchRequest = globalThis.fetch) {
  const values = { filter };
  if (completed) values.completed = '1';
  const response = await fetchRequest(action, {
    method: 'POST',
    headers: { Accept: 'application/json' },
    body: new URLSearchParams(values),
    keepalive: true,
  });
  if (!response.ok) throw new Error('Task completion could not be saved. Please try again.');
}

export function installTaskCompletion(document, save = saveCompletion) {
  const pending = new Set();
  const alert = document.querySelector('#completion-error');

  document.addEventListener('change', (event) => {
    const checkbox = event.target;
    if (!checkbox.matches('form[data-task-completion] input[type="checkbox"][name="completed"]')) return;
    const form = checkbox.form;
    const completed = checkbox.checked;
    const filter = form.elements.filter.value;
    checkbox.disabled = true;
    alert.hidden = true;

    const update = (async () => {
      try {
        await save(form.action, completed, filter);
        if ((filter === 'Open' && completed) || (filter === 'Completed' && !completed)) {
          form.closest('[data-testid="task-row"]').remove();
        }
        return true;
      } catch {
        checkbox.checked = !completed;
        alert.textContent = 'Task completion could not be saved. Please try again.';
        alert.hidden = false;
        return false;
      } finally {
        checkbox.disabled = false;
      }
    })();
    pending.add(update);
    update.finally(() => pending.delete(update));
  });

  // Native navigation must not cancel or overtake an in-flight completion save.
  document.addEventListener('submit', async (event) => {
    if (!pending.size) return;
    event.preventDefault();
    const form = event.target;
    const submitter = event.submitter;
    const saved = await Promise.all([...pending]);
    if (saved.every(Boolean)) form.requestSubmit(submitter || undefined);
  });
}

if (typeof document !== 'undefined') installTaskCompletion(document);

# Workboard

Requires Node.js 22.22.1. No application dependencies or installation step are needed.

Run `npm start` to serve on `0.0.0.0:8080`. Set `PORT` to change the port and
`DB_PATH` to choose the persistent SQLite file (default: `data/workboard.sqlite`).
The parent database directory is created on startup. `GET /health` returns
`{"status":"ok"}`. Stop with SIGINT or SIGTERM to close the server and database.

Run `npm test` for integration checks using temporary databases, including
validation, project navigation, and persistence across server restarts.

Each project supports task creation, completion checkboxes, and an All/Open/Completed
filter. Names and titles are trimmed before saving. Tasks belong to one project;
their order and completion state persist in SQLite. Filters are stored in the page
URL and applied after task changes. Completion changes save in place; native form
navigation waits for pending saves so filter changes cannot cancel them. Failed
saves restore the checkbox and show an alert.
