  env: { ...process.env, PORT: '0', DB_PATH: join(directory, 'workboard.sqlite') },
  detached: true, stdio: ['ignore', 'pipe', 'pipe'],
});
let output = '';
let errors = '';
child.stderr.on('data', chunk => { errors += chunk; });
try {
  const port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error("'`Startup timed out: ${errors}`)), 5000);
    child.once('"'error', error => { clearTimeout(timer); reject(error); });
    child.once('exit', code => { clearTimeout(timer); reject(new Error("'`Exited ${code}: ${errors}`)); });
    child.stdout.on('"'data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
